import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"What is Tradeboard?","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md"}'),i={name:"README.md"};function n(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-tradeboard" tabindex="-1">What is Tradeboard? <a class="header-anchor" href="#what-is-tradeboard" aria-label="Permalink to &quot;What is Tradeboard?&quot;">​</a></h1><p>Tradeboard is a free, open source, self hosted algorithmic trading platform that bridges trading ideas with execution. Built with Python Flask and a modern React frontend, it provides a unified API layer across 36 broker plugins: 34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin for paper trading. It supports automation from Amibroker, TradingView, GoCharting, N8N, ChartInk, MetaTrader 5, Excel, Google Sheets, and a Chrome extension, with six official SDKs: Python, Node.js, Java, .NET, Go, and Rust.</p><h3 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h3><p><strong>Tradeboard</strong> is an <strong>open-source, self-hosted algorithmic trading platform</strong> that makes it easy to build, test, and run trading strategies across multiple Indian brokers using a <strong>single, consistent interface</strong>.</p><p>Beyond execution, Tradeboard empowers traders to completely own their trading infrastructure. Traders can effortlessly build algorithmic strategies, indicators, and custom trading dashboards using AI agentic coding tools, connect with their favorite trading platforms, and deploy strategies without being tied to any single broker or vendor. By standardizing broker APIs into one consistent trading layer, Tradeboard allows strategies to work the same way across brokers, making automation faster, scalable, and fully under the trader’s control.</p><hr><h3 id="what-problem-does-tradeboard-solve" tabindex="-1">What Problem Does Tradeboard Solve? <a class="header-anchor" href="#what-problem-does-tradeboard-solve" aria-label="Permalink to &quot;What Problem Does Tradeboard Solve?&quot;">​</a></h3><p>Tradeboard is built around one core idea: effortlessly create trading strategies using AI tools and run and monitor them like never before. Instead of learning multiple broker APIs and documentation, AI agentic coding tools such as Codex, Claude Code, Antigravity, and OpenCode understand Tradeboard directly. Traders can build strategies faster, create their own algo features, design custom trading alerts, connect to any trading platform of their choice, store historical data, and run analytics or backtesting within a fully self hosted environment. There are no code tool offerings available, and you completely own your data and infrastructure.</p><p>Most brokers expose their own APIs with different authentication methods, order parameters, market data structures, and operational limitations. Tradeboard reduces this friction with common request and response shapes. Exchange coverage, authentication, market-data entitlement, GTT support, and other optional capabilities still vary by plugin and broker account.</p><hr><h3 id="who-should-use-tradeboard" tabindex="-1">Who Should Use Tradeboard? <a class="header-anchor" href="#who-should-use-tradeboard" aria-label="Permalink to &quot;Who Should Use Tradeboard?&quot;">​</a></h3><h4 id="traders" tabindex="-1">Traders <a class="header-anchor" href="#traders" aria-label="Permalink to &quot;Traders&quot;">​</a></h4><p>Tradeboard is suitable for traders who want to:</p><ul><li>Automate rule-based or discretionary strategies</li><li>Execute TradingView, ChartInk, or Amibroker alerts</li><li>Test strategies safely using sandbox testing</li><li>Monitor orders, positions, and profit/loss in real time</li><li>Maintain full control over execution and data</li></ul><p>No coding expertise is required to get started, though advanced users can extend it further.</p><hr><h4 id="developers" tabindex="-1">Developers <a class="header-anchor" href="#developers" aria-label="Permalink to &quot;Developers&quot;">​</a></h4><p>Tradeboard is designed for developers who need:</p><ul><li>A stable and well-documented REST and WebSocket API</li><li>Uniform request and response formats across brokers</li><li>SDKs in multiple programming languages</li><li>A self-hosted, extensible trading backend</li><li>Support for advanced use cases such as AI-driven execution</li></ul><hr><h3 id="key-capabilities" tabindex="-1">Key Capabilities <a class="header-anchor" href="#key-capabilities" aria-label="Permalink to &quot;Key Capabilities&quot;">​</a></h3><h4 id="unified-trading-api" tabindex="-1">Unified Trading API <a class="header-anchor" href="#unified-trading-api" aria-label="Permalink to &quot;Unified Trading API&quot;">​</a></h4><p>Tradeboard exposes a standardized API that allows you to:</p><ul><li>Place, modify, and cancel orders</li><li>Fetch positions, holdings, and funds</li><li>Access orderbook and tradebook</li><li>Retrieve real-time and historical market data</li></ul><p>Broker plugins follow the common API structure for the operations they support.</p><hr><h4 id="multiple-ways-to-run-strategies" tabindex="-1">Multiple Ways to Run Strategies <a class="header-anchor" href="#multiple-ways-to-run-strategies" aria-label="Permalink to &quot;Multiple Ways to Run Strategies&quot;">​</a></h4><p>Tradeboard supports different strategy workflows:</p><ul><li><strong>Hosted Python strategies</strong> running directly inside Tradeboard as separate processes, on an exchange-aware schedule</li><li><strong>Visual Flow strategies</strong> built from 61 node types on a no-code canvas, with schedule, price-alert, webhook, and order-update triggers</li><li><strong>External signals</strong> from TradingView, Amibroker, ChartInk, GoCharting, MetaTrader 5, N8N, Excel, or Google Sheets</li><li><strong>AI agents</strong> connected through the built-in MCP server over local stdio or an OAuth-protected remote HTTP transport</li></ul><p>This flexibility allows users to choose the approach that best fits their experience level.</p><hr><h4 id="portfolio-analysis" tabindex="-1">Portfolio Analysis <a class="header-anchor" href="#portfolio-analysis" aria-label="Permalink to &quot;Portfolio Analysis&quot;">​</a></h4><p>Tradeboard includes two authenticated, read-only portfolio workflows:</p><ul><li><strong>Portfolio Backtester</strong> simulates a target NSE/BSE allocation using Historify or broker history, with rebalancing, drift bands, costs, benchmarks, robustness analysis, and a downloadable HTML tearsheet.</li><li><strong>Portfolio Analyzer</strong> loads current broker holdings and evaluates how today&#39;s market-value allocation would have behaved over a selected historical lookback.</li></ul><p>Neither workflow places or modifies orders. See <a href="./new-features/portfolio-analytics">Portfolio Backtester and Analyzer</a>.</p><hr><h4 id="chart-trading-terminal" tabindex="-1">Chart Trading Terminal <a class="header-anchor" href="#chart-trading-terminal" aria-label="Permalink to &quot;Chart Trading Terminal&quot;">​</a></h4><p>The <code>/trading</code> terminal provides seven persisted layouts, from a single chart to an eight-chart <code>4×2</code> grid. Each pane supports its own symbol, interval, chart type, indicators, drawings, history backfill, market depth, and order entry while sharing one drawing toolbar and the application&#39;s real-time market-data connection.</p><p>See <a href="./new-features/trading-terminal">Chart Trading Terminal</a>.</p><hr><h4 id="scalping-terminal" tabindex="-1">Scalping Terminal <a class="header-anchor" href="#scalping-terminal" aria-label="Permalink to &quot;Scalping Terminal&quot;">​</a></h4><p>The <code>/scalping</code> workspace is keyboard driven. Arrow keys fire call and put orders, F6 flattens every scalping position, and F7 cancels every pending scalping order. A server-side risk monitor evaluates stops, targets, and trailing steps on live ticks, so protection survives closing the browser.</p><p>See <a href="./new-features/fast-scalper">Scalping Terminal</a>.</p><hr><h4 id="options-and-analytics-tools" tabindex="-1">Options and Analytics Tools <a class="header-anchor" href="#options-and-analytics-tools" aria-label="Permalink to &quot;Options and Analytics Tools&quot;">​</a></h4><p>The <code>/tools</code> page collects 18 analytical surfaces:</p><ul><li>strategy builder and strategy portfolio;</li><li>portfolio backtester, portfolio analyzer, and SIP backtester;</li><li>option chain, option Greeks, and option symbol resolution;</li><li>OI tracker, OI range, OI profile, and max pain;</li><li>straddle chart and straddle PnL;</li><li>volatility surface, IV smile, GEX dashboard, and gamma density;</li><li>a futures arbitrage scanner.</li></ul><p>Coverage of a given underlying still depends on the active broker&#39;s option-chain and history entitlement.</p><hr><h4 id="sandbox-testing-environment" tabindex="-1">Sandbox Testing Environment <a class="header-anchor" href="#sandbox-testing-environment" aria-label="Permalink to &quot;Sandbox Testing Environment&quot;">​</a></h4><p>Tradeboard includes a fully isolated <strong>sandbox testing environment</strong> for validating strategies before live deployment.</p><p>Sandbox testing provides:</p><ul><li>Live market data</li><li>Configurable <strong>sandbox capital</strong></li><li>Configurable sandbox margin and order behavior</li><li>Configurable MIS square-off schedules</li><li>Simulated order and account state isolated from live broker execution</li></ul><hr><h4 id="order-control-and-safety" tabindex="-1">Order Control and Safety <a class="header-anchor" href="#order-control-and-safety" aria-label="Permalink to &quot;Order Control and Safety&quot;">​</a></h4><p>Tradeboard offers optional order approval workflows:</p><ul><li>Automatic execution for fully automated strategies</li><li>Manual approval for supervised or discretionary trading</li><li>Full audit trail of all actions</li></ul><p>This helps reduce execution risk and improves transparency.</p><hr><h4 id="security-and-privacy" tabindex="-1">Security and Privacy <a class="header-anchor" href="#security-and-privacy" aria-label="Permalink to &quot;Security and Privacy&quot;">​</a></h4><p>Security and data ownership are core principles of Tradeboard:</p><ul><li>Broker session tokens are encrypted; <code>.env</code> credentials must be protected by the operator</li><li>Passwords are securely hashed</li><li>TOTP two-factor authentication can be enforced independently for dashboard sign-in, remote MCP authorization, and password reset</li><li>API access is rate-limited, and traffic and latency are logged locally</li><li>No user data is collected or shared</li></ul><p>All data remains on infrastructure controlled by the user.</p><hr><h3 id="deployment-and-usage" tabindex="-1">Deployment and Usage <a class="header-anchor" href="#deployment-and-usage" aria-label="Permalink to &quot;Deployment and Usage&quot;">​</a></h3><p>Tradeboard is designed to be self-hosted:</p><ul><li>Run on a local machine</li><li>Deploy on a VPS or cloud server</li><li>Suitable for personal, professional, and team use</li></ul><p>Once installed, it can serve as a central execution engine for all trading strategies.</p><h3 id="what-tradeboard-is-not" tabindex="-1">What Tradeboard is NOT <a class="header-anchor" href="#what-tradeboard-is-not" aria-label="Permalink to &quot;What Tradeboard is NOT&quot;">​</a></h3><p>Let&#39;s be clear about what Tradeboard doesn&#39;t do:</p><table tabindex="0"><thead><tr><th>Misconception</th><th>Reality</th></tr></thead><tbody><tr><td>Get-rich-quick scheme</td><td>It&#39;s a tool - profitability depends on your strategy</td></tr><tr><td>Strategy provider</td><td>You need your own trading ideas</td></tr><tr><td>Financial advisor</td><td>You&#39;re responsible for trading decisions</td></tr><tr><td>Black box</td><td>100% open source - verify every line of code</td></tr><tr><td>Cloud service</td><td>Self-hosted - you control everything</td></tr></tbody></table><h3 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Minimum</th><th>Recommended</th></tr></thead><tbody><tr><td><strong>OS</strong></td><td>Windows 10, macOS 10.15, Ubuntu 20.04</td><td>Latest versions</td></tr><tr><td><strong>Python</strong></td><td>3.12+</td><td>3.12+</td></tr><tr><td><strong>RAM</strong></td><td>2 GB</td><td>2 GB+</td></tr><tr><td><strong>Storage</strong></td><td>2 GB</td><td>10 GB+ (for historical data)</td></tr><tr><td><strong>Network</strong></td><td>Stable internet</td><td>Low latency connection</td></tr></tbody></table><h3 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aspect</th><th>Tradeboard</th></tr></thead><tbody><tr><td><strong>Cost</strong></td><td>Free (Open Source, AGPL License)</td></tr><tr><td><strong>Brokers</strong></td><td>36 plugins: 34 securities brokers, Delta Exchange (crypto), Dhan Sandbox</td></tr><tr><td><strong>Exchanges</strong></td><td>NSE, NFO, BSE, BFO, MCX, CDS, BCD, NCDEX, NCO, plus index and crypto segments</td></tr><tr><td><strong>SDKs</strong></td><td>Python, Node.js, Java, .NET, Go, Rust</td></tr><tr><td><strong>Signal Sources</strong></td><td>TradingView, Amibroker, ChartInk, GoCharting, MetaTrader 5, N8N, Excel, Google Sheets, Python, AI agents</td></tr><tr><td><strong>Strategy Building</strong></td><td>Flow (61 visual node types), Python Hosting, External Webhooks</td></tr><tr><td><strong>Sandbox Trading</strong></td><td>Analyzer Mode with ₹1 Crore sandbox capital</td></tr><tr><td><strong>Historical Data</strong></td><td>Historify with DuckDB storage</td></tr><tr><td><strong>Real-Time Data</strong></td><td>WebSocket streaming for quotes, depth, and order updates</td></tr><tr><td><strong>Options Analytics</strong></td><td>18 tools at <code>/tools</code></td></tr><tr><td><strong>Notifications</strong></td><td>Telegram bot, WhatsApp bot, WebSocket updates</td></tr><tr><td><strong>Data Privacy</strong></td><td>100% - self-hosted on your infrastructure</td></tr><tr><td><strong>Skill Required</strong></td><td>Basic trading knowledge</td></tr></tbody></table><hr>',76)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
